class FeedingEntry {const FeedingEntry({required this.id,required this.petId,required this.at,required this.food,this.amount,this.unit='',this.mealType='Meal',this.note=''});final String id,petId,food,unit,mealType,note;final DateTime at;final double? amount;Map<String,Object?> toMap()=>{'id':id,'petId':petId,'at':at.toIso8601String(),'food':food,'amount':amount,'unit':unit,'mealType':mealType,'note':note};factory FeedingEntry.fromMap(Map<String,Object?> m)=>FeedingEntry(id:m['id'] as String,petId:m['petId'] as String,at:DateTime.parse(m['at'] as String),food:m['food'] as String,amount:(m['amount'] as num?)?.toDouble(),unit:m['unit'] as String? ?? '',mealType:m['mealType'] as String? ?? 'Meal',note:m['note'] as String? ?? '');}
class ActivityEntry {const ActivityEntry({required this.id,required this.petId,required this.type,required this.startedAt,this.durationMinutes,this.distance,this.distanceUnit='mi',this.note=''});final String id,petId,type,distanceUnit,note;final DateTime startedAt;final int? durationMinutes;final double? distance;Map<String,Object?> toMap()=>{'id':id,'petId':petId,'type':type,'startedAt':startedAt.toIso8601String(),'durationMinutes':durationMinutes,'distance':distance,'distanceUnit':distanceUnit,'note':note};factory ActivityEntry.fromMap(Map<String,Object?> m)=>ActivityEntry(id:m['id'] as String,petId:m['petId'] as String,type:m['type'] as String,startedAt:DateTime.parse(m['startedAt'] as String),durationMinutes:m['durationMinutes'] as int?,distance:(m['distance'] as num?)?.toDouble(),distanceUnit:m['distanceUnit'] as String? ?? 'mi',note:m['note'] as String? ?? '');}
class ContactCard {const ContactCard({required this.id,required this.type,required this.name,this.petId,this.phone='',this.address='',this.hours='',this.website='',this.isEmergency=false});final String id,type,name,phone,address,hours,website;final String? petId;final bool isEmergency;Map<String,Object?> toMap()=>{'id':id,'type':type,'name':name,'petId':petId,'phone':phone,'address':address,'hours':hours,'website':website,'isEmergency':isEmergency?1:0};factory ContactCard.fromMap(Map<String,Object?> m)=>ContactCard(id:m['id'] as String,type:m['type'] as String,name:m['name'] as String,petId:m['petId'] as String?,phone:m['phone'] as String? ?? '',address:m['address'] as String? ?? '',hours:m['hours'] as String? ?? '',website:m['website'] as String? ?? '',isEmergency:m['isEmergency']==1);}
